/// Conformance against docs/fixtures/protocol_fixtures.json.
///
/// These fixtures are generated by the Python simulator. If this suite fails,
/// the phone and the simulator have drifted apart and packets from one will
/// not be understood by the other.
library;

import 'dart:convert';
import 'dart:io';

import 'package:avertis/mesh/protocol/packet.dart';
import 'package:flutter_test/flutter_test.dart';

void main() {
  final fixtures = jsonDecode(
    File('test/protocol_fixtures.json').readAsStringSync(),
  ) as Map<String, dynamic>;

  group('canonical JSON and payload hashing', () {
    for (final (i, raw) in (fixtures['payload_hashes'] as List).indexed) {
      final c = raw as Map<String, dynamic>;
      test('case $i matches the Python encoder', () {
        final payload = Map<String, dynamic>.from(c['payload'] as Map);
        expect(canonicalJson(payload), c['canonical_json']);
        expect(payloadHashOf(payload), c['payload_hash']);
      });
    }
  });

  group('packet encoding', () {
    for (final (i, raw) in (fixtures['packets'] as List).indexed) {
      final c = raw as Map<String, dynamic>;
      final created = Map<String, dynamic>.from(c['created'] as Map);

      test('packet $i round-trips through JSON', () {
        final packet = Packet.fromJson(created);
        expect(packet.toJson(), equals(created));
      });

      test('packet $i encodes byte-identically to Python', () {
        final packet = Packet.fromJson(created);
        expect(utf8.decode(packet.encode()), c['encoded']);
      });

      test('packet $i forwards identically to Python', () {
        final packet = Packet.fromJson(created);
        final hopped = packet.forwardedBy('node-12').forwardedBy('node-31');
        expect(hopped.toJson(), equals(c['after_two_hops']));
      });
    }
  });

  group('relay scoring', () {
    for (final (i, raw) in (fixtures['relay_scores'] as List).indexed) {
      final c = raw as Map<String, dynamic>;
      test('score $i matches the frozen weights', () {
        final inputs = c['inputs'] as Map<String, dynamic>;
        final score = relayScore(
          battery: (inputs['battery'] as num).toDouble(),
          neighborCount: inputs['neighbor_count'] as int,
          gatewayDistance: inputs['gateway_distance'] as int?,
          linkStability: (inputs['link_stability'] as num).toDouble(),
          mobilityMps: (inputs['mobility_mps'] as num).toDouble(),
        );
        expect(
          double.parse(score.toStringAsFixed(6)),
          closeTo((c['relay_score'] as num).toDouble(), 1e-9),
        );
      });
    }
  });

  test('ISO-8601 formatting matches the protocol', () {
    final ts = DateTime.utc(2026, 9, 6, 12, 0, 0);
    expect(isoOf(ts), '2026-09-06T12:00:00.000Z');
    expect(isoOf(DateTime.utc(2026, 9, 6, 12, 0, 0, 123)),
        '2026-09-06T12:00:00.123Z');
  });

  test('HELLO is never forwardable', () {
    final hello = Packet.create(
      packetId: 'pkt-1',
      originNode: 'node-01',
      destination: broadcast,
      messageType: MessageType.hello,
      priority: Priority.normal,
      createdAt: DateTime.utc(2026, 9, 6, 12),
    );
    expect(hello.ttl, 1);
    expect(hello.forwardedBy('node-02').ttl, 0);
  });

  test('priority ordering is critical-first', () {
    final priorities = [
      Priority.normal,
      Priority.lifeCritical,
      Priority.operational,
      Priority.emergency,
    ]..sort((a, b) => a.rank.compareTo(b.rank));
    expect(priorities.first, Priority.lifeCritical);
    expect(priorities.last, Priority.normal);
  });
}
